      /* 5 in a line → 4 + 1, the best of them advanced (the CAM) toward the attack */
      const best=g.slice().sort((a,b)=>ovrOf(b)-ovrOf(a)||num(b['Proj pts'])-num(a['Proj pts']))[0];
      const rest=g.filter(p=>p!==best);
