  const was=hpMemo('was|'+D.gwsDone,()=>{const s={};(D.gl||[]).forEach(r=>{if(num(r.GW)===D.gwsDone&&r.Started==='XI')s[String(r.Code)+'|'+r.Team]=1});return s});
